const buildLocale = (locale: WesternLocale): Record<string, string> => ({
  ...en,
  ...Object.fromEntries(Object.entries(copy).map(([key, value]) => [key, value[locale]])),
});

export const fr = buildLocale("fr");
export const de = buildLocale("de");
export const it = buildLocale("it");
export const ptBR = buildLocale("pt-BR");
